public struct VaultStatus {
    public var path: String
    public var exists: Bool
    public var unlocked: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(path: String, exists: Bool, unlocked: Bool) {
        self.path = path
        self.exists = exists
        self.unlocked = unlocked
    }
}



extension VaultStatus: Equatable, Hashable {
    public static func ==(lhs: VaultStatus, rhs: VaultStatus) -> Bool {
        if lhs.path != rhs.path {
            return false
        }
        if lhs.exists != rhs.exists {
            return false
        }
        if lhs.unlocked != rhs.unlocked {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(path)
        hasher.combine(exists)
        hasher.combine(unlocked)
    }
}


