public enum FfiError {

    
    
    /**
     * Vault operations were attempted before [`crate::ZeroTerm::unlock`]
     * or [`crate::ZeroTerm::create`] succeeded.
     */
    case VaultLocked
    /**
     * Master password rejected. The vault file is intact; retry with the
     * correct password.
     */
    case AuthenticationFailed
    /**
     * `unlock` was called against a path that has no vault yet.
     */
    case NotInitialized
    /**
     * `create` was called against a path that already has a vault.
     */
    case AlreadyExists
    case NotFound(message: String
    )
    /**
     * Catch-all for anything that doesn't fit a more specific case —
     * IO errors, malformed records, name collisions, etc. The `message`
     * is `Display` of the underlying error.
     */
    case Other(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .VaultLocked
        case 2: return .AuthenticationFailed
        case 3: return .NotInitialized
        case 4: return .AlreadyExists
        case 5: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Other(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .VaultLocked:
            writeInt(&buf, Int32(1))
        
        
        case .AuthenticationFailed:
            writeInt(&buf, Int32(2))
        
        
        case .NotInitialized:
            writeInt(&buf, Int32(3))
        
        
        case .AlreadyExists:
            writeInt(&buf, Int32(4))
        
        
        case let .NotFound(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Other(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


extension FfiError: Equatable, Hashable {}

extension FfiError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}

